def first_heading(path: Path) -> str:
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return path.name


def extract_one_line_thesis(path: Path) -> str:
    lines = path.read_text(encoding="utf-8").splitlines()
    capture = False
    for line in lines:
        if line.strip() == "## One-line thesis":
            capture = True
            continue
        if capture and line.startswith("## "):
            break
        if capture:
            stripped = line.strip()
            if stripped:
                return stripped
    return ""


def keyword_matches(haystack: str, keyword: str) -> bool:
    """Match tag keywords on word/phrase boundaries, not arbitrary substrings.

    The archive previously allowed substring hits such as ``heat`` inside
    ``theater`` or ``rent`` inside ``different``.  Hyphens and spaces are
    treated as equivalent inside multi-word governance phrases, but the
    phrase must still begin and end on an alphanumeric boundary.
    """
    cleaned = " ".join(keyword.lower().split())
    if not cleaned:
        return False
    pattern = re.escape(cleaned).replace(r"\ ", r"[\s\-]+")
    return re.search(rf"(?<![a-z0-9]){pattern}(?![a-z0-9])", haystack) is not None


def infer_tags(*parts: str) -> list[str]:
    haystack = " ".join(parts).lower()
    tags = []
    for tag, keywords in TAG_RULES.items():
        if any(keyword_matches(haystack, keyword) for keyword in keywords):
            tags.append(tag)
    return sorted(tags)


def load_note_metadata() -> dict[str, dict]:
    path = METADATA_DIR / "note_metadata.json"
    if not path.exists():
        return {}
    data = json.loads(path.read_text(encoding="utf-8"))
    return data.get("notes", {})


def main() -> None:
    GENERATED.mkdir(exist_ok=True)
    metadata_notes = load_note_metadata()
    items = []
    for path in numbered_archive_paths():
        m = NUMBERED_NOTE_FILENAME_RE.fullmatch(path.name)
        if not m:
            continue
        number = int(m.group(1))
        slug = m.group(2)
        rel = str(path.relative_to(ROOT))
        title = first_heading(path)
        thesis = extract_one_line_thesis(path)
        meta = metadata_notes.get(rel, {})
        tags = meta.get("tags") or infer_tags(slug, title, thesis)
        entry = {
            "number": number,
            "file": rel,
            "title": title,
            "thesis": thesis,
            "tags": sorted(tags),
        }
        for key in [
            "revision",
            "note_class",
            "status",
            "canon_role",
            "first_citation",
            "depends_on",
            "reserved_notes",
            "dispatcher",
            "source_keys",
        ]:
            if key in meta:
                entry[key] = meta[key]
        items.append(entry)

    data = {
        "revision": CURRENT_REV,
        "generated_at_utc": generated_at_utc(),
        "metadata_source": "metadata/note_metadata.json",
        "count": len(items),
        "notes": items,
    }
    # ARCHIVE_INDEX is a machine route consumed by other generators. Keep the
    # Markdown front doors readable and the machine surface compact.
    (GENERATED / "ARCHIVE_INDEX.json").write_text(json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
    print("OK: wrote generated/ARCHIVE_INDEX.json")


if __name__ == "__main__":
    main()
